/* Course-first navigation. Optional drills are explicitly outside the textbook route. */
(()=>{
 'use strict';
 const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const done=(s,c)=>(c.missions||[]).filter(m=>s.tasks['book:'+c.id+':'+m.id]).length;
 const learned=(s,l)=>(l.rules||[]).filter((_,i)=>s.tasks['learn:'+l.id+':'+i]).length;
 function card(l,c,s,i){const n=done(s,c),all=c.missions.length,k=learned(s,l),pc=all?Math.round(n/all*100):0;return `<article class="course-node" style="--chapter-hue:${[190,260,170,220,280,190,240,170][i%8]}"><div class="node-top"><span class="node-number">${String(i+1).padStart(2,'0')}</span><span class="node-type">教材原题 · ${all} 组</span></div><h3>${esc(l.title)}</h3><p>${esc(l.subtitle)}</p><div class="node-stages"><span class="${k===l.rules.length?'complete':''}">◇ 学习 ${k}/${l.rules.length}</span><span class="${n===all?'complete':''}">⚑ 原题 ${n}/${all}</span></div><progress max="${Math.max(1,all)}" value="${n}" aria-label="${esc(l.title)} 原题进度"></progress><div class="node-bottom"><small>${pc}% 已完成 · 含对照自评</small><button class="primary small" data-course="${esc(l.id)}">${k||n?'继续这一章':'开始这一章'} →</button></div></article>`}
 function bind(host,ctx){host.querySelectorAll('[data-course]').forEach(b=>b.onclick=()=>ctx.openCourse(b.dataset.course))}
 function home(host,ctx){const s=ctx.state,d=ctx.data,courses=d.courses||[],lessons=d.lessons.filter(l=>courses.some(c=>c.id===l.id));const groups=courses.reduce((n,c)=>n+c.missions.length,0),finished=courses.reduce((n,c)=>n+done(s,c),0),study=lessons.reduce((n,l)=>n+learned(s,l),0),unitDone=d.units.filter(u=>s.results['unit-'+u.id]?.score===s.results['unit-'+u.id]?.total&&s.results['unit-'+u.id]?.total).length;const next=courses.find(c=>done(s,c)<c.missions.length)||courses[0],nextLesson=lessons.find(l=>l.id===next?.id),lv=ctx.level;const act=Object.keys(s.activity).length,reviewCount=courses.reduce((n,c)=>n+c.missions.filter(m=>s.results['book:'+c.id+':'+m.id]?.reviewNeed).length,0);
  host.innerHTML=`<div class="journey-heading"><div><div class="eyebrow">YOUR EXAM QUEST</div><h1>${esc(s.settings.name||'同学')}，今天再闯一关。</h1><p>理解一个知识点，练熟一组书上题。每一步，都离考场更近。</p></div><span class="signal-pill"><span class="connection-dot"></span>教材优先 · 逐关推进</span></div><section class="hero quest-hero"><div><span class="quest-kicker">THE TEXTBOOK IS YOUR MAP</span><h2>把书上的每道题，<br><span>练到熟悉。</span></h2><p>这里的备考主线来自你提供的教材与听力材料。先理解，再作答，再核对；把还不熟的题留给下一轮。</p><div class="button-row"><button class="primary" data-course="${esc(next?.id||'sentence')}">继续学习 · ${esc(nextLesson?.title||'Sentence skills')} ↗</button><button class="secondary" data-go="writing">查看章节地图</button></div><div class="quest-meta"><span>${study} 个知识点已学</span><span>${finished} 组原题已练</span><span>${act} 天留下进步</span></div></div><div class="quest-orbit" aria-label="原题关卡完成进度"><div class="quest-orbit-ring"></div><div class="quest-orbit-core"><span>TEXTBOOK QUESTS</span><strong>${finished}<small> / ${groups}</small></strong><span>原题关卡 · 含自评</span><div class="quest-level">LV. ${String(lv.level).padStart(2,'0')} · ${lv.xp} XP</div></div><span class="orbit-dot one"></span><span class="orbit-dot two"></span></div></section><div class="quest-stats"><div><span>核心教材</span><strong>${courses.length}<small> 个专题</small></strong></div><div><span>书上练习</span><strong>${groups}<small> 组原题关卡</small></strong></div><div><span>听力原题</span><strong>121<small> 个填空</small></strong></div><div><span>听力全对</span><strong>${unitDone}<small> / 8 单元</small></strong></div></div><section class="route-explainer"><div><span>01</span><strong>分步学习</strong><p>一个屏幕，一个知识点</p></div><i>→</i><div><span>02</span><strong>原题闯关</strong><p>书上原题，按组练习</p></div><i>→</i><div><span>03</span><strong>即时复盘</strong><p>客观题核对，开放题对照</p></div></section><div class="section-head space-top"><div><div class="card-kicker">CHOOSE YOUR NEXT CHAPTER</div><h2>从这三站，开启下一步</h2></div><button class="quiet" data-go="writing">全部章节 →</button></div><div class="course-map preview-map">${lessons.slice(0,3).map((l,i)=>card(l,courses.find(c=>c.id===l.id),s,i)).join('')}</div><div class="quest-bottom-grid"><a class="listening-portal" href="#listening"><span class="portal-icon">◎</span><div><div class="card-kicker">LISTENING LAB</div><h2>原声听力挑战</h2><p>8 个单元 · 原始音频 · 逐篇练习与逐空反馈</p></div><span>↗</span></a><a class="review-portal" href="#mistakes"><span class="card-kicker">RETRY & GROW</span><h2>回到还没掌握的题</h2><p>${reviewCount} 组原题待复习 · ${Object.keys(s.mistakes).length} 条其他错题 · 每次复习都更靠近掌握 →</p></a></div><p class="scope-caption">按你确认的“期末来自教材练习”安排主线；具体题量、分值及抽题范围仍以教师通知为准。词汇与自编题仅作辅助，可在<a href="#tools">辅助工具</a>中使用。</p>`;bind(host,ctx)
 }
 function catalog(host,ctx){const d=ctx.data,s=ctx.state,courses=d.courses||[],core=d.lessons.filter(l=>courses.some(c=>c.id===l.id)),extra=d.lessons.filter(l=>!courses.some(c=>c.id===l.id));host.innerHTML=`<div class="journey-heading"><div><div class="eyebrow">TEXTBOOK LEARNING MAP</div><h1>一章一章，把书练熟。</h1><p>章节内将学习和练习分开。进度自动保存，随时回来继续下一步。</p></div><span class="signal-pill">${core.length} 个核心专题</span></div><div class="map-intro"><span class="map-compass">✧</span><div><strong>先理解，再闯关。</strong><p>学习卡片是教材规则的中文讲解；原题关卡展示书上题目和配套答案。原题组数不等于考试题量。</p></div></div><div class="course-map">${core.map((l,i)=>card(l,courses.find(c=>c.id===l.id),s,i)).join('')}</div><details class="panel supplementary-chapters space-top"><summary>补充阅读 · RA、引用规范与编辑建议（${extra.length} 个专题）</summary><p class="hint">来自资料包的补充内容，尚无独立考试项目依据，不计入八章原题关卡。</p><div class="supplement-list">${extra.map(l=>`<button class="secondary" data-course="${esc(l.id)}">${esc(l.title)} →</button>`).join('')}</div></details>`;bind(host,ctx)}
 function tools(host){host.innerHTML=`<div class="journey-heading"><div><div class="eyebrow">OPTIONAL STUDY TOOLS</div><h1>需要时，再用这些辅助工具。</h1><p>它们帮助理解和巩固，不代表期末设有对应考试项目。</p></div></div><div class="tool-cards"><a href="#vocabulary" class="panel"><span class="tag">辅助复习 · 非独立考项</span><h2>词汇与短语卡</h2><p>原指令要求从材料整理词汇，方便基础恢复。未找到独立词汇考试的依据；听力填空短语仍要结合原题练熟。</p><span class="quiet">按需复习 →</span></a><a href="#mocks" class="panel"><span class="tag">自编拓展 · 不是教材原题</span><h2>两套拓展模拟练习</h2><p>此前按教材题型自编，不能保证考试会出现。优先完成教材原题后，再用来检验迁移能力。</p><span class="quiet">打开自编练习 →</span></a><a href="#freewriting" class="panel"><span class="tag">自由草稿 · 非考试要求</span><h2>写作草稿桌</h2><p>保留你的作文草稿、自查与下载功能。教材指定写作任务请在对应章节原题关卡完成。</p><span class="quiet">继续写作 →</span></a></div><div class="button-row"><button class="primary" data-go="writing">返回教材主线 →</button><button class="secondary" data-go="settings">账号与偏好</button></div>`}
 window.StudyJourney={home,catalog,tools};
})();
